import { Command } from 'commander';
import { spawn } from 'child_process';

export function registerRemote(program: Command) {
  program
    .command('remote <sshUrl> <gitCommand...>')
    .description('Execute git commands over SSH')
    .action((sshUrl: string, gitCommand: string[]) => {
      const cmd = ['ssh', sshUrl, 'git', ...gitCommand];
      const child = spawn(cmd[0], cmd.slice(1), { stdio: 'inherit' });
      child.on('exit', code => process.exit(code || 0));
    });
}
